function MediaPanel({ block, onProps, background, onBackground, embedded = false }: { block: PageBlock; onProps: (props: Record<string, unknown>) => void; background: PageConfig["background"]; onBackground: (patch: Partial<PageConfig["background"]>) => void; embedded?: boolean }) {
  const inputRef = useRef<HTMLInputElement>(null); const isBanner = block.type === "banner"; const isProfile = block.type === "profile"; const mediaKey = isBanner ? "imageUrl" : isProfile ? "avatarUrl" : "url"; const value = String(block.props[mediaKey] ?? "");
  const load = (file?: File) => { if (!file) return; if (!file.type.startsWith("image/")) return toast.error("Selecciona un archivo de imagen válido."); if (file.size > 2_500_000) return toast.error("Usa una imagen de hasta 2,5 MB en el candidato local."); const reader = new FileReader(); reader.onload = () => onProps({ [mediaKey]: String(reader.result) }); reader.readAsDataURL(file); };
  const reset = () => onProps(isBanner ? { imageUrl: "", imageOpacity: 100, overlayOpacity: 25, positionX: 50, positionY: 50, fit: "cover", radius: 0, style: defaultBlockStyle() } : isProfile ? { avatarUrl: "", size: 72, shape: "circle", borderWidth: 0, shadow: 18, align: "center", style: defaultBlockStyle() } : { url: "", alt: "", radius: 14, positionX: 50, positionY: 50, fit: "cover", style: defaultBlockStyle() });
  if (isProfile) return <div className="ep-panel ep-media-panel"><div className="ep-inline-add"><button onClick={() => inputRef.current?.click()}><ImageIcon size={15} />{value ? "Reemplazar imagen" : "Subir imagen"}</button><input ref={inputRef} className="ep-hidden-input" type="file" accept="image/*" onChange={event => load(event.target.files?.[0])} /></div><label className="ep-field">URL de imagen<input value={value} placeholder="https://..." onChange={event => onProps({ [mediaKey]: event.target.value })} /></label><PrecisionControl label="Tamaño" value={Number(block.props.size ?? 72)} min={42} max={144} suffix=" px" onChange={size => onProps({ size })} /><div className="ep-choice-grid">{["circle", "rounded", "square"].map(shape => <button className={block.props.shape === shape ? "is-selected" : ""} key={shape} onClick={() => onProps({ shape })}>{shape}</button>)}</div><div className="ep-color-row"><label>Borde<input type="color" value={String(block.props.borderColor ?? "#c49a68")} onChange={event => onProps({ borderColor: event.target.value })} /></label><label>Alineación<select value={String(block.props.align ?? "center")} onChange={event => onProps({ align: event.target.value })}><option value="left">Izquierda</option><option value="center">Centro</option><option value="right">Derecha</option></select></label></div><PrecisionControl label="Ancho de borde" value={Number(block.props.borderWidth ?? 0)} min={0} max={12} suffix=" px" onChange={borderWidth => onProps({ borderWidth })} /><PrecisionControl label="Sombra" value={Number(block.props.shadow ?? 18)} min={0} max={40} suffix=" px" onChange={shadow => onProps({ shadow })} /><ItemImageControl label="Logo independiente" value={String(block.props.logoUrl ?? "")} onChange={logoUrl => onProps({ logoUrl })} /><PrecisionControl label="Ancho de logo" value={Number(block.props.logoWidth ?? 120)} min={32} max={240} suffix=" px" onChange={logoWidth => onProps({ logoWidth })} /><button className="ep-reset-control" onClick={reset}>Restablecer ajustes</button></div>;
  if (block.type === "image") { const visual = getBlockStyle(block); const updateFilters = (patch: Partial<BlockVisualStyle["filters"]>) => onProps({ style: { ...visual, filters: { ...visual.filters, ...patch } } }); return <div className="ep-panel ep-media-panel"><div className="ep-inline-add"><button onClick={() => inputRef.current?.click()}><ImageIcon size={15} />{value ? "Reemplazar imagen" : "Subir imagen"}</button><input ref={inputRef} className="ep-hidden-input" type="file" accept="image/*" onChange={event => load(event.target.files?.[0])} /></div><label className="ep-field">URL de imagen<input value={value} placeholder="https://..." onChange={event => onProps({ url: event.target.value })} /></label><label className="ep-field">Texto alternativo<input value={String(block.props.alt ?? "")} onChange={event => onProps({ alt: event.target.value })} /></label><PrecisionControl label="Opacidad" value={visual.filters.opacity} min={0} max={100} suffix="%" onChange={opacity => updateFilters({ opacity })} /><PrecisionControl label="Brillo" value={visual.filters.brightness} min={40} max={160} suffix="%" onChange={brightness => updateFilters({ brightness })} /><PrecisionControl label="Contraste" value={visual.filters.contrast} min={40} max={160} suffix="%" onChange={contrast => updateFilters({ contrast })} /><PrecisionControl label="Saturación" value={visual.filters.saturation} min={0} max={180} suffix="%" onChange={saturation => updateFilters({ saturation })} /><PrecisionControl label="Escala de grises" value={visual.filters.grayscale} min={0} max={100} suffix="%" onChange={grayscale => updateFilters({ grayscale })} /><PrecisionControl label="Desenfoque" value={visual.filters.blur} min={0} max={16} suffix=" px" onChange={blur => updateFilters({ blur })} /><button className="ep-reset-control" onClick={reset}>Restablecer ajustes</button></div>; }
  return <div className={embedded ? "ep-media-panel" : "ep-panel ep-media-panel"}><div className="ep-inline-add"><button onClick={() => inputRef.current?.click()}><ImageIcon size={15} />{value ? "Reemplazar imagen" : "Subir imagen"}</button><input ref={inputRef} className="ep-hidden-input" type="file" accept="image/*" onChange={event => load(event.target.files?.[0])} /><span>{value ? "Preview activo" : "Local / URL"}</span></div><label className="ep-field">URL de imagen<input value={value} placeholder="https://..." onChange={event => onProps({ [mediaKey]: event.target.value })} /></label>{value && <div className="ep-media-preview"><img alt={String(block.props.alt ?? "Preview de medio")} src={value} /><button onClick={() => onProps({ [mediaKey]: "" })}><Trash2 size={14} />Eliminar</button></div>}<div className="ep-color-row"><label>Encaje / recorte<select value={String(block.props.fit ?? "cover")} onChange={event => onProps({ fit: event.target.value })}><option value="cover">Cover</option><option value="contain">Contain</option></select></label>{!isProfile && <label>Radio<input type="number" min="0" max="48" value={Number(block.props.radius ?? 0)} onChange={event => onProps({ radius: Number(event.target.value) })} /></label>}</div>{!isProfile && <><PrecisionControl label="Posición X" value={Number(block.props.positionX ?? 50)} min={0} max={100} suffix="%" onChange={positionX => onProps({ positionX })} /><PrecisionControl label="Posición Y" value={Number(block.props.positionY ?? 50)} min={0} max={100} suffix="%" onChange={positionY => onProps({ positionY })} /></>}{isBanner && <><PrecisionControl label="Altura" value={Number(block.props.height ?? 126)} min={80} max={230} suffix=" px" onChange={height => onProps({ height })} /><PrecisionControl label="Opacidad de imagen" value={Number(block.props.imageOpacity ?? 100)} min={0} max={100} suffix="%" onChange={imageOpacity => onProps({ imageOpacity })} /><div className="ep-color-row"><label>Overlay<input type="color" value={String(block.props.overlayColor ?? "#11141c")} onChange={event => onProps({ overlayColor: event.target.value })} /></label><label>Fusión<select value={String(block.props.blend ?? "soft")} onChange={event => onProps({ blend: event.target.value })}><option value="none">Ninguna</option><option value="soft">Suave</option><option value="medium">Media</option><option value="intense">Intensa</option></select></label></div><PrecisionControl label="Opacidad overlay" value={Number(block.props.overlayOpacity ?? 25)} min={0} max={100} suffix="%" onChange={overlayOpacity => onProps({ overlayOpacity })} /><PrecisionControl label="Fuerza de fusión" value={Number(block.props.blendStrength ?? 40)} min={0} max={100} suffix="%" onChange={blendStrength => onProps({ blendStrength })} /><label className="ep-switch"><span>Gradiente de página</span><input type="checkbox" checked={background.gradient} onChange={event => onBackground({ gradient: event.target.checked })} /><i /></label><PrecisionControl label="Ángulo de gradiente" value={background.angle} min={0} max={360} suffix="°" onChange={angle => onBackground({ angle })} /></>}<button className="ep-reset-control" onClick={reset}>Restablecer ajustes</button></div>;
}

function ItemImageControl({ value, onChange, label = "Imagen" }: { value: string; onChange: (value: string) => void; label?: string }) {
  const inputRef = useRef<HTMLInputElement>(null);
  const load = (file?: File) => { if (!file) return; if (!file.type.startsWith("image/")) return toast.error("Selecciona una imagen válida."); if (file.size > 2_500_000) return toast.error("Usa una imagen de hasta 2,5 MB."); const reader = new FileReader(); reader.onload = () => onChange(String(reader.result)); reader.readAsDataURL(file); };
  return <><label className="ep-field">{label}<input value={value} placeholder="URL de imagen" onChange={event => onChange(event.target.value)} /></label><div className="ep-inline-add"><button onClick={() => inputRef.current?.click()}><ImageIcon size={14} />Subir</button><input ref={inputRef} className="ep-hidden-input" type="file" accept="image/*" onChange={event => load(event.target.files?.[0])} />{value && <button onClick={() => onChange("")}><Trash2 size={14} />Quitar</button>}</div></>;
}

function FooterPanel({ page, block, onCommit, onProps }: { page: PageConfig; block: PageBlock; onCommit: (next: PageConfig) => void; onProps: (props: Record<string, unknown>) => void }) {
  const canRemoveBranding = page.capabilities.canRemoveCripqerBranding;
  return <div className="ep-panel"><label className="ep-switch"><span>Mostrar footer</span><input type="checkbox" checked={block.enabled} onChange={event => onCommit(updateBlock(page, block.id, { enabled: event.target.checked }))} /><i /></label><label className="ep-field">Texto superior<input value={String(block.props.topText ?? "")} onChange={event => onProps({ topText: event.target.value })} /></label><label className="ep-field">Texto inferior<input value={String(block.props.bottomText ?? block.props.text ?? "")} onChange={event => onProps({ bottomText: event.target.value })} /></label><label className="ep-switch"><span>Diseñado con Cripqer</span><input type="checkbox" checked={page.branding.showCripqerWatermark || !canRemoveBranding} disabled={!canRemoveBranding} onChange={event => onCommit({ ...page, branding: { ...page.branding, showCripqerWatermark: event.target.checked } })} /><i /></label>{!canRemoveBranding && <p className="ep-guidance">La marca oficial permanece visible en este perfil.</p>}<div className="ep-color-row"><label>Alineación<select value={String(block.props.align ?? "center")} onChange={event => onProps({ align: event.target.value })}><option value="left">Izquierda</option><option value="center">Centro</option><option value="right">Derecha</option></select></label><label>Preset<select value={String(block.props.preset ?? "minimal")} onChange={event => onProps({ preset: event.target.value })}><option value="minimal">Minimal</option><option value="centered">Centered</option><option value="brand">Brand</option><option value="legal">Legal/simple</option></select></label></div><label className="ep-field">Fuente<select value={String(block.props.fontFamily ?? "DM Mono")} onChange={event => onProps({ fontFamily: event.target.value })}><option>DM Mono</option><option>Manrope</option><option>Playfair Display</option><option>Space Grotesk</option></select></label><div className="ep-color-row"><label>Color<input type="color" value={String(block.props.color ?? "#aeb3bb")} onChange={event => onProps({ color: event.target.value })} /></label><label className="ep-switch"><span>Divisor</span><input type="checkbox" checked={Boolean(block.props.divider)} onChange={event => onProps({ divider: event.target.checked })} /><i /></label></div><PrecisionControl label="Tamaño" value={Number(block.props.fontSize ?? 7)} min={7} max={18} suffix=" px" onChange={fontSize => onProps({ fontSize })} /><PrecisionControl label="Opacidad" value={Number(block.props.opacity ?? 70)} min={15} max={100} suffix="%" onChange={opacity => onProps({ opacity })} /><PrecisionControl label="Padding" value={getBlockStyle(block).composition.padding} min={0} max={32} suffix=" px" onChange={padding => onProps({ style: { ...getBlockStyle(block), composition: { ...getBlockStyle(block).composition, padding } } })} /></div>;
}

function BannerCompositionPanel({ block, onProps }: { block: PageBlock; onProps: (props: Record<string, unknown>) => void }) {
  const mode = String(block.props.fusionMode ?? "hard");
  return <div className="ep-banner-fusion-panel"><p className="ep-guidance"><Waves size={14} /> Fusión visual del banner con el fondo de la landing.</p><details open><summary>Fusión</summary><label className="ep-field">Modo<select value={mode} onChange={event => onProps({ fusionMode: event.target.value })}><option value="hard">Recto</option><option value="soft">Fusión</option><option value="custom">Personalizado</option></select></label>{mode !== "hard" && <PrecisionControl label="Profundidad" value={Number(block.props.fusionDepth ?? 46)} min={16} max={80} suffix="%" onChange={fusionDepth => onProps({ fusionDepth })} />}{mode === "custom" && <PrecisionControl label="Fuerza" value={Number(block.props.fusionStrength ?? 100)} min={0} max={100} suffix="%" onChange={fusionStrength => onProps({ fusionStrength })} />}</details><p className="ep-guidance">Recto conserva el borde; Fusión desvanece la base; Personalizado controla la transición sin editar la imagen.</p></div>;
}

function AvatarCompositionPanel({ block, onProps }: { block: PageBlock; onProps: (props: Record<string, unknown>) => void }) {
  const vertical = String(block.props.verticalPosition ?? "body");
  return <div className="ep-panel ep-advanced-panel"><p className="ep-guidance"><Move size={14} /> Posición estructural del avatar, sin coordenadas libres.</p><details open><summary>Región y solapamiento</summary><label className="ep-field">Región vertical<select value={vertical} onChange={event => onProps({ verticalPosition: event.target.value })}><option value="banner">Dentro del banner</option><option value="transition">Entre banner y contenido</option><option value="body">Dentro del contenido</option></select></label><label className="ep-field">Alineación<select value={String(block.props.align ?? "center")} onChange={event => onProps({ align: event.target.value })}><option value="left">Izquierda</option><option value="center">Centro</option><option value="right">Derecha</option></select></label>{vertical !== "body" && <PrecisionControl label="Solapamiento" value={Number(block.props.overlap ?? 34)} min={0} max={96} suffix=" px" onChange={overlap => onProps({ overlap })} />}</details></div>;
}

function SocialPanel({ block, onProps }: { block: PageBlock; onProps: (props: Record<string, unknown>) => void }) {
  const items = getSocials(block); const addNetwork = () => onProps({ items: [...items, { id: `social-${Date.now()}`, network: "instagram", url: "https://instagram.com", enabled: true }] }); const move = (from: number, to: number) => onProps({ items: reorder(items, from, to) }); const networks: SocialItem["network"][] = ["instagram", "facebook", "tiktok", "x", "linkedin", "whatsapp", "youtube", "telegram", "email", "website"];
  return <div className="ep-panel"><div className="ep-inline-add"><button onClick={addNetwork}><Plus size={15} /> Agregar red</button><span>{items.length} activas</span></div><label className="ep-field">Alineación<select value={String(block.props.align ?? "center")} onChange={event => onProps({ align: event.target.value })}><option value="left">Izquierda</option><option value="center">Centro</option><option value="right">Derecha</option></select></label>{items.map((item, index) => <div className="ep-social-edit" key={item.id}><select value={item.network} onChange={event => onProps({ items: items.map(current => current.id === item.id ? { ...current, network: event.target.value as SocialItem["network"] } : current) })}>{networks.map(network => <option key={network}>{network}</option>)}</select><input value={item.url} onChange={event => onProps({ items: items.map(current => current.id === item.id ? { ...current, url: event.target.value } : current) })} /><span><button aria-label="Subir red" disabled={!index} onClick={() => move(index, index - 1)}><ChevronUp size={12} /></button><button aria-label="Bajar red" disabled={index === items.length - 1} onClick={() => move(index, index + 1)}><ChevronDown size={12} /></button><button aria-label="Eliminar red" onClick={() => onProps({ items: items.filter(current => current.id !== item.id) })}><Trash2 size={14} /></button></span></div>)}<div className="ep-color-row"><label>Color<input type="color" value={String(block.props.color ?? "#c9cbd0")} onChange={event => onProps({ color: event.target.value })} /></label><label>Estilo<select value={String(block.props.socialStyle ?? "simple")} onChange={event => onProps({ socialStyle: event.target.value })}><option value="simple">Simple</option><option value="pills">Pills</option></select></label></div><PrecisionControl label="Tamaño" value={Number(block.props.size ?? 18)} min={12} max={32} suffix=" px" onChange={size => onProps({ size })} /><PrecisionControl label="Gap" value={Number(block.props.gap ?? 10)} min={4} max={28} suffix=" px" onChange={gap => onProps({ gap })} /><button className="ep-reset-control" onClick={() => onProps({ align: "center", gap: 10, size: 18, color: "#c9cbd0", socialStyle: "simple", background: "transparent", radius: 0 })}>Restablecer redes</button></div>;
}

function CardsPanel({ block, onProps }: { block: PageBlock; onProps: (props: Record<string, unknown>) => void }) {
  const items = (block.props.items ?? []) as Array<{ id: string; title: string; description: string; cta?: string; ctaUrl?: string; imageUrl?: string; objectPosition?: string }>;
  const update = (id: string, patch: Partial<(typeof items)[number]>) => onProps({ items: items.map(item => item.id === id ? { ...item, ...patch } : item) });
  const move = (index: number, to: number) => onProps({ items: reorder(items, index, to) });
  return <div className="ep-panel"><div className="ep-inline-add"><button onClick={() => onProps({ items: [...items, { id: `card-${Date.now()}`, title: "Nueva tarjeta", description: "Describe este contenido", cta: "Saber más", ctaUrl: "", imageUrl: "", objectPosition: "50% 50%" }] })}><Plus size={15} /> Agregar tarjeta</button><span>{items.length} tarjeta(s)</span></div><label className="ep-field">Columnas<select value={Number(block.props.layout ?? 1)} onChange={event => onProps({ layout: Number(event.target.value) })}><option value={1}>Una</option><option value={2}>Dos</option></select></label>{items.map((item, index) => <div className="ep-item-editor" key={item.id}><b>Tarjeta {index + 1}</b><input value={item.title} placeholder="Título" onChange={event => update(item.id, { title: event.target.value })} /><input value={item.description} placeholder="Descripción" onChange={event => update(item.id, { description: event.target.value })} /><ItemImageControl value={item.imageUrl ?? ""} onChange={imageUrl => update(item.id, { imageUrl })} /><label className="ep-field">Posición de imagen<select value={item.objectPosition ?? "50% 50%"} onChange={event => update(item.id, { objectPosition: event.target.value })}><option value="50% 50%">Centro</option><option value="50% 20%">Arriba</option><option value="50% 80%">Abajo</option><option value="20% 50%">Izquierda</option><option value="80% 50%">Derecha</option></select></label><input value={item.cta ?? ""} placeholder="Texto CTA" onChange={event => update(item.id, { cta: event.target.value })} /><input value={item.ctaUrl ?? ""} placeholder="URL CTA" onChange={event => update(item.id, { ctaUrl: event.target.value })} /><div className="ep-panel-actions"><button disabled={!index} onClick={() => move(index, index - 1)}><ChevronUp size={14} />Subir</button><button disabled={index === items.length - 1} onClick={() => move(index, index + 1)}><ChevronDown size={14} />Bajar</button><button onClick={() => onProps({ items: [...items, { ...item, id: `card-${Date.now()}`, title: `${item.title} (copia)` }] })}><Copy size={14} />Duplicar</button><button onClick={() => onProps({ items: items.filter(current => current.id !== item.id) })}><Trash2 size={14} />Eliminar</button></div></div>)}<SurfaceControls block={block} onProps={onProps} label="tarjetas" /></div>;
}

function VideoPanel({ block, onProps }: { block: PageBlock; onProps: (props: Record<string, unknown>) => void }) {
  const items = (block.props.items ?? []) as Array<{ id: string; title: string; url: string }>;
  const update = (id: string, patch: Partial<(typeof items)[number]>) => onProps({ items: items.map(item => item.id === id ? { ...item, ...patch } : item) });
  return <div className="ep-panel"><div className="ep-inline-add"><button onClick={() => onProps({ items: [...items, { id: `video-${Date.now()}`, title: `Vídeo ${items.length + 1}`, url: "" }] })}><Plus size={15} /> Agregar vídeo</button><span>{items.length} vídeo(s)</span></div><label className="ep-field">Layout<select value={String(block.props.layout ?? "full")} onChange={event => onProps({ layout: event.target.value })}><option value="full">Ancho completo</option><option value="two-column">Dos columnas</option></select></label><label className="ep-field">Aspect ratio<select value={String(block.props.aspectRatio ?? "16:9")} onChange={event => onProps({ aspectRatio: event.target.value })}><option>16:9</option><option>1:1</option><option>4:5</option></select></label>{items.map((item, index) => <div className="ep-item-editor" key={item.id}><b>Vídeo {index + 1}</b><input value={item.title} onChange={event => update(item.id, { title: event.target.value })} /><input value={item.url} placeholder="YouTube, Vimeo o URL embed" onChange={event => update(item.id, { url: event.target.value })} /><div className="ep-panel-actions"><button onClick={() => onProps({ items: [...items, { ...item, id: `video-${Date.now()}`, title: `${item.title} (copia)` }] })}><Copy size={14} />Duplicar</button><button onClick={() => onProps({ items: items.filter(current => current.id !== item.id) })}><Trash2 size={14} />Eliminar</button></div></div>)}<SurfaceControls block={block} onProps={onProps} label="vídeo" /><p className="ep-guidance"><Eye size={14} /> La tarjeta respeta el formato elegido y abre la URL configurada únicamente en Vista previa.</p></div>;
}

function SurfaceControls({ block, onProps, label }: { block: PageBlock; onProps: (props: Record<string, unknown>) => void; label: string }) { const style = getBlockStyle(block); const update = (patch: Partial<BlockVisualStyle>) => onProps({ style: { ...style, ...patch, composition: { ...style.composition, ...patch.composition }, border: { ...style.border, ...patch.border } } }); return <><div className="ep-color-row"><label>Fondo<input type="color" value={String(block.props.background ?? "#242832")} onChange={event => onProps({ background: event.target.value })} /></label><label>Texto<input type="color" value={String(block.props.color ?? "#f5f3ee")} onChange={event => onProps({ color: event.target.value })} /></label></div><PrecisionControl label="Radio" value={style.border.radius} min={0} max={32} suffix=" px" onChange={radius => update({ border: { ...style.border, radius } })} /><PrecisionControl label="Padding" value={style.composition.padding} min={0} max={32} suffix=" px" onChange={padding => update({ composition: { ...style.composition, padding } })} /><button className="ep-reset-control" onClick={() => onProps({ background: undefined, color: undefined, style: defaultBlockStyle() })}>Restablecer {label}</button></>; }

function AdvancedPanel({ page, block, breakpoint, onCommit, onExport, onImport }: { page: PageConfig; block: PageBlock; breakpoint: Breakpoint; onCommit: (page: PageConfig) => void; onExport: () => void; onImport: () => void }) {
  const [presetName, setPresetName] = useState(""); const style = getBlockStyle(block); const premium = page.capabilities.allowAdvancedStyles; const supportsColumns = ["links", "video", "cards", "gallery", "services", "reviews", "products", "faq"].includes(block.type); const supportsFontOverride = ["heading", "text", "footer", "profile", "links", "cards", "services", "reviews", "products", "booking", "faq", "contact", "map"].includes(block.type);
  const update = (patch: Partial<BlockVisualStyle>) => onCommit(updateBlockStyle(page, block.id, patch)); const updateComposition = (patch: Partial<BlockVisualStyle["composition"]>) => update({ composition: { ...style.composition, ...patch } }); const updateResponsive = (patch: Partial<ResponsiveOverride>) => update({ responsive: { ...style.responsive, [breakpoint]: { ...style.responsive[breakpoint], ...patch } } });
  if (!premium) return <div className="ep-panel ep-select-panel"><WandSparkles size={24} /><p>Los acabados avanzados están disponibles en el perfil Premium. El contenido existente no se elimina al cambiar de perfil.</p></div>;
  return <div className={`ep-panel ep-advanced-panel ep-advanced-${block.type}`}><p className="ep-guidance"><SlidersHorizontal size={14} /> Controles colapsados y persistibles para {getBlockLabel(block).toLowerCase()}.</p>
    <details><summary>Composición</summary><PrecisionControl label="Margen superior" value={style.composition.marginTop} min={0} max={80} suffix=" px" onChange={marginTop => updateComposition({ marginTop })} /><PrecisionControl label="Margen inferior" value={style.composition.marginBottom} min={0} max={80} suffix=" px" onChange={marginBottom => updateComposition({ marginBottom })} /><PrecisionControl label="Padding" value={style.composition.padding} min={0} max={48} suffix=" px" onChange={padding => updateComposition({ padding })} /><PrecisionControl label="Gap" value={style.composition.gap} min={0} max={32} suffix=" px" onChange={gap => updateComposition({ gap })} /><PrecisionControl label="Ancho" value={style.composition.width} min={20} max={100} suffix="%" onChange={width => updateComposition({ width })} /><PrecisionControl label="Ancho máximo" value={style.composition.maxWidth} min={20} max={100} suffix="%" onChange={maxWidth => updateComposition({ maxWidth })} /><PrecisionControl label="Altura mínima" value={style.composition.minHeight} min={0} max={300} suffix=" px" onChange={minHeight => updateComposition({ minHeight })} /><div className="ep-color-row"><label>Alineación horizontal<select value={style.composition.align} onChange={event => updateComposition({ align: event.target.value as BlockVisualStyle["composition"]["align"] })}><option value="left">Izquierda</option><option value="center">Centro</option><option value="right">Derecha</option></select></label><label>Alineación vertical<select value={style.composition.verticalAlign} onChange={event => updateComposition({ verticalAlign: event.target.value as BlockVisualStyle["composition"]["verticalAlign"] })}><option value="top">Arriba</option><option value="middle">Centro</option><option value="bottom">Abajo</option></select></label></div>{supportsColumns && <PrecisionControl label="Columnas" value={style.composition.columns} min={1} max={3} onChange={columns => updateComposition({ columns })} />}</details>
    <details><summary>Borde y sombra</summary><div className="ep-color-row"><label>Estilo<select value={style.border.style} onChange={event => update({ border: { ...style.border, style: event.target.value as BlockVisualStyle["border"]["style"] } })}><option value="none">Sin borde</option><option value="solid">Sólido</option><option value="dashed">Dashed</option><option value="dotted">Dotted</option><option value="double">Doble</option></select></label><label>Color<input type="color" value={style.border.color} onChange={event => update({ border: { ...style.border, color: event.target.value } })} /></label></div><PrecisionControl label="Ancho de borde" value={style.border.width} min={0} max={12} suffix=" px" onChange={width => update({ border: { ...style.border, width } })} /><PrecisionControl label="Opacidad borde" value={style.border.opacity} min={0} max={100} suffix="%" onChange={opacity => update({ border: { ...style.border, opacity } })} /><PrecisionControl label="Radio" value={style.border.radius} min={0} max={64} suffix=" px" onChange={radius => update({ border: { ...style.border, radius } })} /><div className="ep-color-row"><label>Preset<select value={style.shadow.preset} onChange={event => update({ shadow: { ...style.shadow, preset: event.target.value as BlockVisualStyle["shadow"]["preset"] } })}><option value="none">Ninguna</option><option value="soft">Soft</option><option value="floating">Floating</option><option value="deep">Deep</option><option value="premium">Premium</option><option value="glow">Glow</option></select></label><label>Color<input type="color" value={style.shadow.color} onChange={event => update({ shadow: { ...style.shadow, color: event.target.value } })} /></label></div><PrecisionControl label="Sombra X" value={style.shadow.x} min={-30} max={30} suffix=" px" onChange={x => update({ shadow: { ...style.shadow, x } })} /><PrecisionControl label="Sombra Y" value={style.shadow.y} min={-30} max={40} suffix=" px" onChange={y => update({ shadow: { ...style.shadow, y } })} /><PrecisionControl label="Blur" value={style.shadow.blur} min={0} max={80} suffix=" px" onChange={blur => update({ shadow: { ...style.shadow, blur } })} /><PrecisionControl label="Spread" value={style.shadow.spread} min={-20} max={40} suffix=" px" onChange={spread => update({ shadow: { ...style.shadow, spread } })} /></details>
    <details><summary>Glow, glass y mezcla</summary><div className="ep-color-row"><label>Glow<select value={style.glow.preset} onChange={event => update({ glow: { ...style.glow, preset: event.target.value as BlockVisualStyle["glow"]["preset"] } })}><option value="none">Ninguno</option><option value="white">Blanco</option><option value="gold">Gold</option><option value="blue">Blue neon</option><option value="pink">Pink neon</option><option value="purple">Purple neon</option></select></label><label>Color<input type="color" value={style.glow.color} onChange={event => update({ glow: { ...style.glow, color: event.target.value } })} /></label></div><PrecisionControl label="Intensidad glow" value={style.glow.intensity} min={0} max={100} suffix="%" onChange={intensity => update({ glow: { ...style.glow, intensity } })} /><PrecisionControl label="Blur glow" value={style.glow.blur} min={0} max={80} suffix=" px" onChange={blur => update({ glow: { ...style.glow, blur } })} /><label className="ep-switch"><span>Glassmorphism</span><input type="checkbox" checked={style.glass.enabled} onChange={event => update({ glass: { ...style.glass, enabled: event.target.checked } })} /><i /></label><div className="ep-color-row"><label>Tint<input type="color" value={style.glass.tint} onChange={event => update({ glass: { ...style.glass, tint: event.target.value } })} /></label><label>Mezcla<select value={style.blendMode} onChange={event => update({ blendMode: event.target.value as BlockVisualStyle["blendMode"] })}><option value="normal">Normal</option><option value="multiply">Multiply</option><option value="screen">Screen</option><option value="overlay">Overlay</option><option value="soft-light">Soft light</option></select></label></div><PrecisionControl label="Transparencia" value={style.glass.transparency} min={0} max={100} suffix="%" onChange={transparency => update({ glass: { ...style.glass, transparency } })} /><PrecisionControl label="Backdrop blur" value={style.glass.blur} min={0} max={40} suffix=" px" onChange={blur => update({ glass: { ...style.glass, blur } })} /></details>
    <details><summary>Gradiente y filtros</summary><label className="ep-switch"><span>Gradiente del bloque</span><input type="checkbox" checked={style.gradient.enabled} onChange={event => update({ gradient: { ...style.gradient, enabled: event.target.checked } })} /><i /></label><div className="ep-color-row"><label>Tipo<select value={style.gradient.type} onChange={event => update({ gradient: { ...style.gradient, type: event.target.value as BlockVisualStyle["gradient"]["type"] } })}><option value="linear">Lineal</option><option value="radial">Radial</option></select></label><label>Inicio<input type="color" value={style.gradient.start} onChange={event => update({ gradient: { ...style.gradient, start: event.target.value } })} /></label><label>Medio<input type="color" value={style.gradient.middle} onChange={event => update({ gradient: { ...style.gradient, middle: event.target.value } })} /></label><label>Final<input type="color" value={style.gradient.end} onChange={event => update({ gradient: { ...style.gradient, end: event.target.value } })} /></label></div><PrecisionControl label="Ángulo" value={style.gradient.angle} min={0} max={360} suffix="°" onChange={angle => update({ gradient: { ...style.gradient, angle } })} /><PrecisionControl label="Brillo" value={style.filters.brightness} min={40} max={160} suffix="%" onChange={brightness => update({ filters: { ...style.filters, brightness } })} /><PrecisionControl label="Contraste" value={style.filters.contrast} min={40} max={160} suffix="%" onChange={contrast => update({ filters: { ...style.filters, contrast } })} /><PrecisionControl label="Saturación" value={style.filters.saturation} min={0} max={180} suffix="%" onChange={saturation => update({ filters: { ...style.filters, saturation } })} /><PrecisionControl label="Opacidad" value={style.filters.opacity} min={0} max={100} suffix="%" onChange={opacity => update({ filters: { ...style.filters, opacity } })} /><label className="ep-field">Máscara<select value={style.mask} onChange={event => update({ mask: event.target.value as BlockVisualStyle["mask"] })}><option value="none">Ninguna</option><option value="circle">Círculo</option><option value="rounded">Rounded</option><option value="arch">Arco</option><option value="blob">Blob</option><option value="organic">Orgánica</option><option value="hexagon">Hexágono</option></select></label></details>
    <details><summary>Animación</summary><label className="ep-field">Entrada / movimiento<select value={style.motion.preset} onChange={event => update({ motion: { ...style.motion, preset: event.target.value as BlockVisualStyle["motion"]["preset"] } })}><option value="none">Ninguna</option><option value="fade">Fade</option><option value="slide-up">Slide up</option><option value="slide-down">Slide down</option><option value="slide-left">Slide left</option><option value="slide-right">Slide right</option><option value="zoom">Zoom</option><option value="soft-bounce">Soft bounce</option><option value="blur-in">Blur in</option><option value="float">Float</option><option value="pulse">Pulse</option><option value="slow-rotate">Slow rotate</option><option value="glow-pulse">Glow pulse</option><option value="drift">Drift</option></select></label><PrecisionControl label="Duración" value={style.motion.duration} min={150} max={6000} step={50} suffix=" ms" onChange={duration => update({ motion: { ...style.motion, duration } })} /><PrecisionControl label="Delay" value={style.motion.delay} min={0} max={3000} step={50} suffix=" ms" onChange={delay => update({ motion: { ...style.motion, delay } })} /><label className="ep-switch"><span>Loop</span><input type="checkbox" checked={style.motion.loop} onChange={event => update({ motion: { ...style.motion, loop: event.target.checked } })} /><i /></label></details>
    <details><summary>Responsive · {breakpoint}</summary><label className="ep-switch"><span>Ocultar en {breakpoint}</span><input type="checkbox" checked={Boolean(style.responsive[breakpoint].hidden)} onChange={event => updateResponsive({ hidden: event.target.checked })} /><i /></label>{supportsColumns && <PrecisionControl label="Columnas override" value={Number(style.responsive[breakpoint].columns ?? style.composition.columns)} min={1} max={3} onChange={columns => updateResponsive({ columns })} />}<PrecisionControl label="Gap override" value={Number(style.responsive[breakpoint].gap ?? style.composition.gap)} min={0} max={32} suffix=" px" onChange={gap => updateResponsive({ gap })} />{supportsFontOverride && <PrecisionControl label="Fuente override" value={Number(style.responsive[breakpoint].fontSize ?? 16)} min={8} max={60} suffix=" px" onChange={fontSize => updateResponsive({ fontSize })} />}<label className="ep-field">Alineación override<select value={style.responsive[breakpoint].align ?? style.composition.align} onChange={event => updateResponsive({ align: event.target.value as ResponsiveOverride["align"] })}><option value="left">Izquierda</option><option value="center">Centro</option><option value="right">Derecha</option></select></label></details>
    <details><summary>Presets y JSON</summary><div className="ep-inline-add"><input value={presetName} placeholder="Nombre del preset" onChange={event => setPresetName(event.target.value)} /><button onClick={() => { if (!presetName.trim()) return toast.error("Nombra el preset antes de guardarlo."); onCommit(saveStylePreset(page, presetName.trim(), "effects", block)); setPresetName(""); toast.success("Preset de estilo guardado."); }}><Save size={14} />Guardar preset</button></div>{page.presets.map(preset => <button className="ep-preset-button" key={preset.id} onClick={() => onCommit(applyStylePreset(page, block.id, preset.id))}>{preset.name}<small>{preset.category}</small></button>)}<div className="ep-panel-actions"><button onClick={onExport}><Download size={14} />Exportar JSON</button><button onClick={onImport}><Import size={14} />Importar JSON</button></div></details>
  </div>;
}

function DecorationPanel({ block, onProps }: { block: PageBlock; onProps: (props: Record<string, unknown>) => void }) {
  const position = <label className="ep-field">Posición<select value={String(block.props.position ?? "top-right")} onChange={event => onProps({ position: event.target.value })}><option value="top-left">Arriba izquierda</option><option value="top-right">Arriba derecha</option><option value="bottom-left">Abajo izquierda</option><option value="bottom-right">Abajo derecha</option></select></label>;
  if (block.type === "shape") return <div className="ep-panel"><label className="ep-field">Forma<select value={String(block.props.shape ?? "circle")} onChange={event => onProps({ shape: event.target.value })}><option value="circle">Círculo</option><option value="ellipse">Elipse</option><option value="square">Cuadrado</option><option value="triangle">Triángulo</option><option value="star">Estrella</option><option value="blob">Blob</option></select></label><div className="ep-color-row"><label>Relleno<input type="color" value={String(block.props.color ?? "#c49a68")} onChange={event => onProps({ color: event.target.value })} /></label><label>Trazo<input type="color" value={String(block.props.stroke ?? "#f5f3ee")} onChange={event => onProps({ stroke: event.target.value })} /></label></div>{position}<PrecisionControl label="Tamaño" value={Number(block.props.size ?? 86)} min={12} max={220} suffix=" px" onChange={size => onProps({ size })} /><PrecisionControl label="Opacidad" value={Number(block.props.opacity ?? 55)} min={5} max={100} suffix="%" onChange={opacity => onProps({ opacity })} /><PrecisionControl label="Rotación" value={Number(block.props.rotation ?? 0)} min={0} max={360} suffix="°" onChange={rotation => onProps({ rotation })} /></div>;
  if (block.type === "ring") return <div className="ep-panel"><label className="ep-field">Estilo<select value={String(block.props.partial ? "partial" : "full")} onChange={event => onProps({ partial: event.target.value === "partial" })}><option value="full">Anillo completo</option><option value="partial">Arco parcial</option></select></label><label className="ep-field">Color<input type="color" value={String(block.props.color ?? "#c49a68")} onChange={event => onProps({ color: event.target.value })} /></label>{position}<PrecisionControl label="Tamaño" value={Number(block.props.size ?? 108)} min={24} max={260} suffix=" px" onChange={size => onProps({ size })} /><PrecisionControl label="Grosor" value={Number(block.props.thickness ?? 2)} min={1} max={14} suffix=" px" onChange={thickness => onProps({ thickness })} /></div>;
  if (block.type === "ornament") return <div className="ep-panel"><label className="ep-field">Preset<select value={String(block.props.preset ?? "gold-corner")} onChange={event => onProps({ preset: event.target.value })}><option value="gold-corner">Gold corner</option><option value="minimal-corner">Minimal corner</option><option value="art-deco">Art deco</option></select></label><label className="ep-field">Color<input type="color" value={String(block.props.color ?? "#c49a68")} onChange={event => onProps({ color: event.target.value })} /></label>{position}<PrecisionControl label="Tamaño" value={Number(block.props.size ?? 52)} min={16} max={150} suffix=" px" onChange={size => onProps({ size })} /><PrecisionControl label="Grosor" value={Number(block.props.thickness ?? 2)} min={1} max={8} suffix=" px" onChange={thickness => onProps({ thickness })} /><PrecisionControl label="Opacidad" value={Number(block.props.opacity ?? 75)} min={5} max={100} suffix="%" onChange={opacity => onProps({ opacity })} /></div>;
  if (block.type === "frame") return <div className="ep-panel"><label className="ep-field">Preset<select value={String(block.props.preset ?? "double")} onChange={event => onProps({ preset: event.target.value })}><option value="minimal">Minimal</option><option value="gold">Gold</option><option value="platinum">Platinum</option><option value="silver">Silver</option><option value="art-deco">Art Deco</option><option value="luxury">Luxury</option><option value="editorial">Editorial</option><option value="single">Borde simple</option><option value="double">Borde doble</option><option value="corners">Corner only</option></select></label><label className="ep-field">Color<input type="color" value={String(block.props.color ?? "#c49a68")} onChange={event => onProps({ color: event.target.value })} /></label><PrecisionControl label="Inset" value={Number(block.props.inset ?? 12)} min={0} max={80} suffix=" px" onChange={inset => onProps({ inset })} /><PrecisionControl label="Grosor" value={Number(block.props.thickness ?? 1)} min={1} max={8} suffix=" px" onChange={thickness => onProps({ thickness })} /><PrecisionControl label="Radio" value={Number(block.props.radius ?? 22)} min={0} max={64} suffix=" px" onChange={radius => onProps({ radius })} /><PrecisionControl label="Opacidad" value={Number(block.props.opacity ?? 45)} min={5} max={100} suffix="%" onChange={opacity => onProps({ opacity })} /></div>;
  if (block.type === "particles") return <div className="ep-panel"><label className="ep-field">Preset<select value={String(block.props.preset ?? "soft-dots")} onChange={event => onProps({ preset: event.target.value })}><option value="soft-dots">Soft dots</option><option value="sparkles">Sparkles</option><option value="stars">Stars</option><option value="gold-dust">Gold dust</option><option value="silver-dust">Silver dust</option><option value="fireflies">Fireflies</option><option value="soft-bokeh">Soft bokeh</option><option value="floating-circles">Floating circles</option><option value="bubbles">Bubbles</option><option value="luxury-shimmer">Luxury shimmer</option><option value="snow">Snow</option><option value="light-flecks">Light flecks</option><option value="gradient-motes">Gradient motes</option><option value="dust">Dust</option><option value="subtle-confetti">Subtle confetti</option></select></label><label className="ep-field">Color<input type="color" value={String(block.props.color ?? "#c49a68")} onChange={event => onProps({ color: event.target.value })} /></label><PrecisionControl label="Cantidad" value={Number(block.props.quantity ?? 14)} min={1} max={28} onChange={quantity => onProps({ quantity })} /><PrecisionControl label="Tamaño" value={Number(block.props.size ?? 3)} min={1} max={18} suffix=" px" onChange={size => onProps({ size })} /><PrecisionControl label="Opacidad" value={Number(block.props.opacity ?? 35)} min={5} max={100} suffix="%" onChange={opacity => onProps({ opacity })} /><PrecisionControl label="Velocidad" value={Number(block.props.speed ?? 8)} min={3} max={24} suffix=" s" onChange={speed => onProps({ speed })} /><label className="ep-field">Dirección<select value={String(block.props.direction ?? "up")} onChange={event => onProps({ direction: event.target.value })}><option value="up">Subir</option><option value="down">Bajar</option><option value="left">Izquierda</option><option value="right">Derecha</option></select></label></div>;
  return <div className="ep-panel"><label className="ep-field">Estilo<select value={String(block.props.dividerStyle ?? "solid")} onChange={event => onProps({ dividerStyle: event.target.value })}><option value="solid">Sólido</option><option value="dashed">Dashed</option><option value="dotted">Dotted</option><option value="gradient">Gradiente</option></select></label><label className="ep-field">Color<input type="color" value={String(block.props.color ?? "#c49a68")} onChange={event => onProps({ color: event.target.value })} /></label><PrecisionControl label="Grosor" value={Number(block.props.width ?? 1)} min={1} max={8} suffix=" px" onChange={width => onProps({ width })} /></div>;
}

function ContentBlockPanel({ block, onProps }: { block: PageBlock; onProps: (props: Record<string, unknown>) => void }) {
  if (block.type === "spacer") return <div className="ep-panel"><PrecisionControl label="Altura" value={Number(block.props.height ?? 24)} min={4} max={180} suffix=" px" onChange={height => onProps({ height })} /></div>;
  if (["booking", "contact", "map"].includes(block.type)) return <div className="ep-panel"><label className="ep-field">Título<input value={String(block.props.title ?? "")} onChange={event => onProps({ title: event.target.value })} /></label><label className="ep-field">Descripción<input value={String(block.props.description ?? block.props.address ?? "")} onChange={event => onProps(block.type === "map" ? { address: event.target.value } : { description: event.target.value })} /></label>{block.type !== "map" && <><label className="ep-field">CTA<input value={String(block.props.cta ?? "")} onChange={event => onProps({ cta: event.target.value })} /></label><label className="ep-field">URL<input value={String(block.props.url ?? block.props.email ?? "")} onChange={event => onProps(block.type === "contact" ? { email: event.target.value } : { url: event.target.value })} /></label></>}</div>;
  const items = (block.props.items ?? []) as Array<{ id: string; title?: string; description?: string; url?: string; price?: string; cta?: string; imageUrl?: string; avatarUrl?: string; rating?: number; featured?: boolean }>;
  const type = block.type; const add = () => { const common = { id: `${type}-${Date.now()}`, title: type === "reviews" ? "" : `Nuevo ${getBlockLabel(block).slice(0, -1).toLowerCase()}`, description: "", url: "" }; onProps({ items: [...items, type === "reviews" ? { ...common, avatarUrl: "", featured: false } : common] }); }; const update = (id: string, patch: Record<string, unknown>) => onProps({ items: items.map(item => item.id === id ? { ...item, ...patch } : item) }); const move = (index: number, to: number) => onProps({ items: reorder(items, index, to) }); const canColumns = ["gallery", "services", "products", "reviews", "faq"].includes(type);
  return <div className="ep-panel"><div className="ep-inline-add"><button onClick={add}><Plus size={15} />Agregar {getBlockLabel(block).toLowerCase()}</button><span>{items.length} item(s)</span></div>{canColumns && <label className="ep-field">Columnas / layout{type === "reviews" ? <select value={String(block.props.layout ?? "cards")} onChange={event => onProps({ layout: event.target.value })}><option value="cards">Cards</option><option value="grid">Grid</option><option value="featured">Featured</option></select> : <select value={String(block.props.layout ?? 1)} onChange={event => onProps({ layout: Number(event.target.value) })}><option value={1}>Una</option><option value={2}>Dos</option><option value={3}>Tres</option></select>}</label>}{type === "gallery" && <><label className="ep-field">Gap<input type="number" min="0" max="32" value={Number(block.props.gap ?? 8)} onChange={event => onProps({ gap: Number(event.target.value) })} /></label>{items.map((item, index) => <div className="ep-item-editor" key={item.id}><b>Imagen {index + 1}</b><ItemImageControl value={item.url ?? ""} onChange={url => update(item.id, { url })} /><div className="ep-panel-actions"><button disabled={!index} onClick={() => move(index, index - 1)}><ChevronUp size={14} />Subir</button><button disabled={index === items.length - 1} onClick={() => move(index, index + 1)}><ChevronDown size={14} />Bajar</button><button onClick={() => onProps({ items: items.filter(current => current.id !== item.id) })}><Trash2 size={14} />Eliminar</button></div></div>)}</>}{type === "reviews" && !items.length ? <p className="ep-guidance"><Star size={14} />No hay reseñas. Agrega sólo testimonios reales autorizados.</p> : type !== "gallery" && items.map((item, index) => <div className="ep-item-editor" key={item.id}><b>{getBlockLabel(block)} {index + 1}</b><input value={item.title ?? ""} placeholder={type === "reviews" ? "Nombre de la persona" : type === "faq" ? "Pregunta" : "Título"} onChange={event => update(item.id, { title: event.target.value })} /><input value={item.description ?? ""} placeholder={type === "reviews" ? "Texto de reseña real" : type === "faq" ? "Respuesta" : "Descripción"} onChange={event => update(item.id, { description: event.target.value })} />{["services", "products"].includes(type) && <><ItemImageControl value={item.imageUrl ?? ""} onChange={imageUrl => update(item.id, { imageUrl })} /><input value={item.cta ?? ""} placeholder="Texto CTA" onChange={event => update(item.id, { cta: event.target.value })} /></>}{type === "reviews" && <><ItemImageControl label="Avatar" value={item.avatarUrl ?? ""} onChange={avatarUrl => update(item.id, { avatarUrl })} /><label className="ep-field">Rating opcional<select value={String(item.rating ?? 0)} onChange={event => update(item.id, { rating: Number(event.target.value) })}><option value={0}>Sin rating</option><option value={1}>1 estrella</option><option value={2}>2 estrellas</option><option value={3}>3 estrellas</option><option value={4}>4 estrellas</option><option value={5}>5 estrellas</option></select></label><label className="ep-switch"><span>Reseña destacada</span><input type="checkbox" checked={Boolean(item.featured)} onChange={event => update(item.id, { featured: event.target.checked })} /><i /></label></>}{type === "products" && <input value={item.price ?? ""} placeholder="Precio opcional" onChange={event => update(item.id, { price: event.target.value })} />}{["services", "products"].includes(type) && <input value={item.url ?? ""} placeholder="URL CTA" onChange={event => update(item.id, { url: event.target.value })} />}<div className="ep-panel-actions"><button disabled={!index} onClick={() => move(index, index - 1)}><ChevronUp size={14} />Subir</button><button disabled={index === items.length - 1} onClick={() => move(index, index + 1)}><ChevronDown size={14} />Bajar</button><button onClick={() => onProps({ items: items.filter(current => current.id !== item.id) })}><Trash2 size={14} />Eliminar</button></div></div>)}</div>;
}

export function EditorPremiumMobile({ draftBridge }: { draftBridge?: EditorDraftBridge } = {}) { return <EditorCandidate mode="mobile" draftBridge={draftBridge} />; }
export function EditorPremiumDesktop({ draftBridge }: { draftBridge?: EditorDraftBridge } = {}) { return <EditorCandidate mode="desktop" draftBridge={draftBridge} />; }
